import os, json
H = os.path.expanduser('~/fmsts')
E = json.load(open(f'{H}/sheets/removed_energy.json'))

# generated list (names only; resolved against the game's own types at runtime)
open(f'{H}/src/FMDuelist/FmEnergy.g.cs', 'w').write(
    '// <auto-generated> from sheets/removed_energy.json </auto-generated>\nnamespace FMDuelist;\n'
    'static partial class FmEnergyFilter\n{\n'
    '    static readonly string[] RelicNames = { ' + ', '.join(f'"{n}"' for n in E['relics']) + ' };\n'
    '    static readonly string[] PotionNames = { ' + ', '.join(f'"{n}"' for n in E['potions']) + ' };\n'
    '    static readonly string[] EventNames = { ' + ', '.join(f'"{n}"' for n in E.get('events', [])) + ' };\n}\n')

# FmEnergy.cs is hand-maintained now; this script only regenerates FmEnergy.g.cs from the sheet.
sy = f'{H}/sheets/systems.json'
rows = json.load(open(sy))
if not any(r['id'] == 'no_energy_items' for r in rows):
    rows.append({"id": "no_energy_items", "what": "Relics and potions listed in sheets/removed_energy.json never appear in FM runs (shops, rewards, chests, Neow)", "value": len(E['relics']) + len(E['potions']), "hook": "card_pool"})
json.dump(rows, open(sy, 'w'), indent=1)
print('ok', len(E['relics']), len(E['potions']))
